+        // Bob transfers the token out of the safe
+        vm.prank(bob.addr);
+        erc721s[0].transferFrom(address(alice.safe), bob.addr, 5);
+
+        // assert that bob owns the asset
+        assertEq(erc721s[0].ownerOf(5), bob.addr);
+    }
